eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   destinations: () => (/* binding */ destinations),\n/* harmony export */   getSafarisForDestination: () => (/* binding */ getSafarisForDestination)\n/* harmony export */ });\n/* harmony import */ var _tours_data__WEBPACK_IMPORTED_MODULE_0__ = __webpack_require__(/*! ./tours-data */ \"(ssr)/./lib/tours-data.ts\");\n\nconst destinations = [\n    {\n        slug: \"tsavo\",\n        name: \"Tsavo\",\n        tagline: \"Kenya's largest wilderness — red-dusted elephants and endless horizons\",\n        heroImage: \"/images/safaris/safari-experience-tsavo.jpg\",\n        intro: \"Tsavo East and West together form one of the world's largest protected wildlife areas. It's famous for its red-earth elephants — the dust here stains their hides the colour of the soil — plus the Yatta Plateau, Mzima Springs, and rolling savannah that stretches to the horizon. It's also the closest major safari destination to the coast, making it easy to combine with a Watamu beach stay.\",\n        wildlifeHighlights: [\n            \"Large elephant herds (Tsavo’s signature red elephants)\",\n            \"Lions, including the historically maneless Tsavo lions\",\n            \"Rhino sanctuary within Tsavo West\",\n            \"Mzima Springs hippos and crocodiles, viewable from an underwater tank\",\n            \"Yatta Plateau — the world’s longest lava flow\"\n        ],\n        bestSeason: \"June–October (dry season) offers the best game viewing as animals gather near rivers and waterholes. November–May is greener and quieter, with fewer vehicles on the tracks.\",\n        faqs: [\n            {\n                q: \"How far is Tsavo from Watamu/Mombasa?\",\n                a: \"Roughly 3–4 hours by road from the coast, which is why most of our Tsavo safaris depart from and return to Watamu or Mombasa.\"\n            },\n            {\n                q: \"Is Tsavo good for a short safari?\",\n                a: \"Yes — Tsavo East in particular works well for 2–3 day safaris since it's the closest major park to the coast, without the long transfer times Masai Mara requires.\"\n            },\n            {\n                q: \"Will we definitely see elephants?\",\n                a: \"Tsavo has one of Kenya's largest elephant populations, so sightings are very likely, especially near water sources in the dry season — though wildlife viewing is never 100% guaranteed.\"\n            }\n        ]\n    },\n    {\n        slug: \"amboseli\",\n        name: \"Amboseli\",\n        tagline: \"Big-tusker elephants beneath the shadow of Kilimanjaro\",\n        heroImage: \"/images/safaris/safari-inside-tsavo-amboseli.jpg\",\n        intro: \"Amboseli National Park is best known for one unbeatable combination: large elephant herds walking across open plains with Mount Kilimanjaro rising in the background — Africa's classic postcard image. The park's swamps and marshes, fed by underground water from Kilimanjaro's snowmelt, keep it green even in the dry season, drawing wildlife (and photographers) from across the region.\",\n        wildlifeHighlights: [\n            \"Free-ranging elephant herds with Kilimanjaro as a backdrop\",\n            \"Swamp-fed grasslands supporting year-round wildlife\",\n            \"Maasai giraffe, buffalo, zebra and wildebeest\",\n            \"Excellent birdlife around Amboseli’s marshes\"\n        ],\n        bestSeason: \"June–October and January–February are best for clear Kilimanjaro views and concentrated wildlife near the swamps. Clouds more often obscure the mountain during the March–May rains.\",\n        faqs: [\n            {\n                q: \"Can we combine Amboseli with Tsavo?\",\n                a: \"Yes — several of our itineraries combine the two since they’re on the same route, giving you Kilimanjaro views and Tsavo’s red elephants in one trip.\"\n            },\n            {\n                q: \"Is Kilimanjaro visible year-round?\",\n                a: \"The mountain is often cloud-covered, especially during the rains. Early morning is generally the clearest time to photograph it.\"\n            }\n        ]\n    },\n    {\n        slug: \"mara\",\n        name: \"Masai Mara\",\n        tagline: \"Kenya's most famous reserve — home to the Great Migration\",\n        heroImage: \"https://images.pexels.com/photos/631317/pexels-photo-631317.jpeg?auto=compress&cs=tinysrgb&w=1200\",\n        intro: \"The Masai Mara National Reserve is Kenya’s flagship safari destination — an extension of Tanzania’s Serengeti ecosystem, and the stage for the annual wildebeest migration. Beyond the migration, the Mara holds year-round resident populations of lion, leopard, cheetah, and elephant across open grassland that makes for exceptional game viewing at any time of year.\",\n        wildlifeHighlights: [\n            \"The Great Migration — river crossings of wildebeest and zebra (seasonal)\",\n            \"High density of big cats: lion, leopard, cheetah\",\n            \"Large resident elephant and buffalo herds\",\n            \"Maasai cultural visits to local villages\"\n        ],\n        bestSeason: \"July–October for the migration and river crossings. The Mara has good game viewing year-round, but the dry season (Jun–Oct) concentrates wildlife most predictably.\",\n        faqs: [\n            {\n                q: \"How far is the Masai Mara from Watamu?\",\n                a: \"It’s a significant journey — typically a flight via Nairobi is more practical than driving from the coast. Our longer, multi-park itineraries (5+ days) are built around this.\"\n            },\n            {\n                q: \"Is the migration guaranteed?\",\n                a: \"No sighting in nature is ever guaranteed, but July–October gives the strongest odds of witnessing river crossings, based on typical migration patterns.\"\n            }\n        ]\n    },\n    {\n        slug: \"taita\",\n        name: \"Taita Hills\",\n        tagline: \"A private, less-crowded sanctuary between Tsavo East and West\",\n        heroImage: \"/images/safaris/safari-nala-taita.jpg\",\n        intro: \"The Taita Hills Wildlife Sanctuary sits between Tsavo East and Tsavo West, offering a quieter, more exclusive game-viewing experience with fewer vehicles than the main parks. Its varied terrain — hills, forest patches, and open plains — supports a good diversity of wildlife in a relatively compact, easy-to-explore area.\",\n        wildlifeHighlights: [\n            \"Elephant, buffalo, and giraffe in a quieter, less-trafficked setting\",\n            \"Varied terrain — hills, plains and forest patches\",\n            \"Often combined with Tsavo East/West for a fuller circuit\"\n        ],\n        bestSeason: \"June–October (dry season) for the best game concentration, similar to neighbouring Tsavo.\",\n        faqs: [\n            {\n                q: \"Is Taita Hills a standalone destination?\",\n                a: \"It’s usually combined with Tsavo East and/or West as part of a multi-park itinerary rather than visited alone, since it sits right between them.\"\n            }\n        ]\n    }\n];\nfunction getSafarisForDestination(slug) {\n    return _tours_data__WEBPACK_IMPORTED_MODULE_0__.safaris.filter((s)=>s.tabs.includes(slug));\n}\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./lib/destinations-data.ts\n");

